{
  "picks": [
    {
      "headword": "chivalrous",
      "kinds": ["spelling", "sound"],
      "why": "Initial 'ch' is pronounced /ʃ/ rather than /tʃ/, followed by an awkward /vəlr/ transition.",
      "difficulty": 2
    },
    {
      "headword": "hypocrite",
      "kinds": ["spelling", "stress"],
      "why": "Spelling misleads learners to say /haɪp-/ and /-aɪt/ instead of /ˈhɪp.ə.krɪt/.",
      "difficulty": 2
    },
    {
      "headword": "lethargy",
      "kinds": ["stress", "sound"],
      "why": "Stress is on the first syllable unlike Russian летарги́я, and it contains the English /θ/.",
      "difficulty": 3
    },
    {
      "headword": "mischievously",
      "kinds": ["stress", "spelling"],
      "why": "Stress is on the first syllable, and learners almost always mistakenly add an extra syllable ('mis-CHEE-vi-ous-ly').",
      "difficulty": 3
    },
    {
      "headword": "tantalizingly",
      "kinds": ["long"],
      "why": "Five syllables with a difficult transition through /zɪŋ.li/ at the end.",
      "difficulty": 1
    },
    {
      "headword": "unreciprocated",
      "kinds": ["long"],
      "why": "Six syllables with alternating stops where the middle unstressed syllables easily get lost.",
      "difficulty": 2
    },
    {
      "headword": "unscrupulous",
      "kinds": ["cluster", "long"],
      "why": "Contains an awkward /skr/ cluster followed by a medial /pjə/ glide that Russian speakers tend to drop.",
      "difficulty": 2
    }
  ]
}

